class Solution {
    public List<Integer> preorderTraversal(TreeNode root) {
        List<Integer> answer = new ArrayList<>();
        if (root == null) return answer;

        Deque<TreeNode> stack = new ArrayDeque<>();
        stack.push(root);

        while (!stack.isEmpty()) {
            TreeNode node = stack.pop();
            answer.add(node.val); // 弹出即访问，顺序才是根-左-右

            // 栈后进先出，先压右再压左，下一轮才会先弹出左孩子。
            if (node.right != null) stack.push(node.right);
            if (node.left != null) stack.push(node.left);
        }
        return answer;
    }

    public List<Integer> inorderTraversal(TreeNode root) {
        List<Integer> answer = new ArrayList<>();
        Deque<TreeNode> stack = new ArrayDeque<>();
        TreeNode current = root;

        while (current != null || !stack.isEmpty()) {
            while (current != null) {
                stack.push(current); // 先把整条左链压栈，暂不访问
                current = current.left;
            }

            current = stack.pop();
            answer.add(current.val); // 左子树都处理完才访问当前节点
            current = current.right; // 再转入右子树
        }
        return answer;
    }

    public List<Integer> postorderTraversal(TreeNode root) {
        LinkedList<Integer> answer = new LinkedList<>();
        if (root == null) return answer;

        Deque<TreeNode> stack = new ArrayDeque<>();
        stack.push(root);

        while (!stack.isEmpty()) {
            TreeNode node = stack.pop();
            // 头插把弹出序根-右-左翻成左-右-根。
            answer.addFirst(node.val);

            // 先压左再压右，弹出时才会先右后左。
            if (node.left != null) stack.push(node.left);
            if (node.right != null) stack.push(node.right);
        }
        return answer;
    }
}

class Solution {
    public List<Integer> postorderTraversal(TreeNode root) {
        List<Integer> ans = new ArrayList<>();
        if (root == null) {
            return ans;
        }
        Deque<TreeNode> stack1 = new ArrayDeque<>();
        Deque<TreeNode> stack2 = new ArrayDeque<>();
        stack1.push(root);
        while (!stack1.isEmpty()) {
            TreeNode node = stack1.pop();
            // 先按根右左压入 stack2，后面再反过来得到左右根
            stack2.push(node);
            if (node.left != null) {
                stack1.push(node.left);
            }
            // 右孩子后压，会先于左孩子被弹出，从而先进入 stack2
            if (node.right != null) {
                stack1.push(node.right);
            }
        }
        while (!stack2.isEmpty()) {
            ans.add(stack2.pop().val);
        }
        return ans;
    }
}

