class Solution {
    public List<List<Integer>> levelOrder(TreeNode root) {
        List<List<Integer>> answer = new ArrayList<>();
        if (root == null) return answer;

        Queue<TreeNode> queue = new ArrayDeque<>();
        queue.offer(root);

        while (!queue.isEmpty()) {
            int levelSize = queue.size(); // 此刻队列里的节点正好是同一层。
            List<Integer> level = new ArrayList<>(levelSize);

            for (int i = 0; i < levelSize; i++) {
                TreeNode node = queue.poll();
                level.add(node.val);

                // 子节点排到队尾，下一轮才会被当成下一层取出。
                if (node.left != null) queue.offer(node.left);
                if (node.right != null) queue.offer(node.right);
            }
            answer.add(level);
        }
        return answer;
    }
}

import java.util.*;

class Solution {
    public List<List<Integer>> zigzagLevelOrder(TreeNode root) {
        List<List<Integer>> answer = new ArrayList<>();
        if (root == null) return answer;

        Deque<TreeNode> queue = new ArrayDeque<>();
        queue.offer(root);
        boolean leftToRight = true; // 第 1 层从左往右写

        while (!queue.isEmpty()) {
            int levelSize = queue.size(); // 先固定本层个数，新入队的孩子不算进来
            Integer[] level = new Integer[levelSize];

            for (int i = 0; i < levelSize; i++) {
                TreeNode node = queue.poll();
                // poll 仍从左到右；反向层把下标改到数组右端。
                int writeIndex = leftToRight ? i : levelSize - 1 - i;
                level[writeIndex] = node.val;

                if (node.left != null) queue.offer(node.left);
                if (node.right != null) queue.offer(node.right); // 孩子始终左再右入队
            }

            answer.add(Arrays.asList(level));
            leftToRight = !leftToRight; // 下一层换写入方向
        }

        return answer;
    }
}

import java.util.*; // Java 常用集合、队列、堆与数组工具

class Solution {
    public List<Integer> rightSideView(TreeNode root) {
        List<Integer> answer = new ArrayList<>();
        dfs(root, 0, answer);
        return answer;
    }

    private void dfs(TreeNode node, int depth, List<Integer> answer) {
        if (node == null) return;

        // 先右后左，本层第一次到达的就是最右可见节点
        if (depth == answer.size()) {
            answer.add(node.val);
        }

        dfs(node.right, depth + 1, answer);
        dfs(node.left, depth + 1, answer);
    }
}

class Solution {
    public int widthOfBinaryTree(TreeNode root) {
        if (root == null) {
            return 0;
        }
        long ans = 0;
        Queue<Pair> queue = new ArrayDeque<>();
        queue.offer(new Pair(root, 1L)); // 根的完全二叉树下标记为 1
        while (!queue.isEmpty()) {
            int size = queue.size();
            long left = queue.peek().idx; // 本层最左下标作为基准，防止下标溢出
            long first = 0, last = 0;
            for (int i = 0; i < size; i++) {
                Pair cur = queue.poll();
                long idx = cur.idx - left;
                if (i == 0) {
                    first = idx;
                }
                if (i == size - 1) {
                    last = idx;
                }
                if (cur.node.left != null) {
                    queue.offer(new Pair(cur.node.left, idx * 2));
                }
                if (cur.node.right != null) {
                    queue.offer(new Pair(cur.node.right, idx * 2 + 1));
                }
            }
            ans = Math.max(ans, last - first + 1); // 空位也算进两端下标之差
        }
        return (int) ans;
    }

    static class Pair {
        TreeNode node;
        long idx;

        Pair(TreeNode node, long idx) {
            this.node = node;
            this.idx = idx;
        }
    }
}

import java.util.*; // Java 常用集合、队列、堆与数组工具

class Solution {
    public int maxDepth(TreeNode root) {
        // 空树没有节点，深度为 0，同时停下递归。
        if (root == null) return 0;

        int leftDepth = maxDepth(root.left);
        int rightDepth = maxDepth(root.right);

        // 当前深度由更深的一侧决定，再加根这一层。
        return Math.max(leftDepth, rightDepth) + 1;
    }
}

import java.util.*;

class Solution {
    public boolean isBalanced(TreeNode root) {
        return height(root) != -1;
    }

    private int height(TreeNode node) {
        if (node == null) {
            return 0;
        }

        int leftHeight = height(node.left);
        if (leftHeight == -1) {
            return -1; // 左子树已经不平衡，不必再算当前高度。
        }

        int rightHeight = height(node.right);
        if (rightHeight == -1) {
            return -1; // 右子树已经不平衡，同样直接上传。
        }

        if (Math.abs(leftHeight - rightHeight) > 1) {
            return -1; // 当前节点左右高度差超过 1。
        }

        return Math.max(leftHeight, rightHeight) + 1;
    }
}

import java.util.*; // Java 常用集合、队列、堆与数组工具

class Solution {
    private int diameter = 0;

    public int diameterOfBinaryTree(TreeNode root) {
        diameter = 0; // 每次调用重置，空树和重复调用不沿用旧答案。
        depth(root);
        return diameter;
    }

    private int depth(TreeNode node) {
        if (node == null) return 0;

        // 后序先拿到左右高度，才能算经过当前节点的路径。
        int left = depth(node.left);
        int right = depth(node.right);

        // 左右高度之和就是经过当前节点的边数。
        diameter = Math.max(diameter, left + right);

        // 向上只能接一条边，所以只返回较高一侧再加 1。
        return Math.max(left, right) + 1;
    }
}

import java.util.*; // Java 常用集合、队列、堆与数组工具

class Solution {
    public int maxPathSum(TreeNode root) {
        if (root == null) throw new IllegalArgumentException("nonempty tree required");
        long[] best = {Long.MIN_VALUE};
        gain(root, best);
        return Math.toIntExact(best[0]);
    }

    private long gain(TreeNode node, long[] best) {
        if (node == null) return 0;

        // 负收益只会把和变小，当成 0 即不选择这条支路。
        long leftGain = Math.max(gain(node.left, best), 0L);
        long rightGain = Math.max(gain(node.right, best), 0L);

        // 拐点路径可以同时带上左右，用它更新全局最大和。
        best[0] = Math.max(best[0], (long) node.val + leftGain + rightGain);

        // 往父亲延伸只能再接一侧，否则从父节点看会分叉。
        return node.val + Math.max(leftGain, rightGain);
    }
}

class Solution {
    private int best = 0;

    public int longestUnivaluePath(TreeNode root) {
        best = 0; // 每次调用重置，空树和重复调用不沿用旧答案。
        dfs(root);
        return best;
    }

    // 返回从 node 向下、且节点值都等于 node.val 的最长单边边数。
    private int dfs(TreeNode node) {
        if (node == null) {
            return 0;
        }

        int leftDepth = dfs(node.left);
        int rightDepth = dfs(node.right);

        int leftPath = 0;
        int rightPath = 0;

        // 孩子值不同就不能接上这条单边，长度保持 0。
        if (node.left != null && node.left.val == node.val) {
            leftPath = leftDepth + 1;
        }
        if (node.right != null && node.right.val == node.val) {
            rightPath = rightDepth + 1;
        }

        // 左右同值链经过当前节点合成一条路径，用边数之和更新答案。
        best = Math.max(best, leftPath + rightPath);

        // 继续向父节点延伸时只能选择一侧。
        return Math.max(leftPath, rightPath);
    }
}

class Solution {
    public boolean hasPathSum(TreeNode root, int targetSum) {
        return hasPath(root, (long) targetSum);
    }

    private boolean hasPath(TreeNode root, long targetSum) {
        if (root == null) {
            return false; // 空节点不是叶子，不能作为路径终点
        }

        // 只有叶子节点才能结束一条根到叶路径。
        if (root.left == null && root.right == null) {
            return root.val == targetSum;
        }

        long remaining = targetSum - root.val; // 当前节点的值已经用掉

        // 左右子树只要有一侧存在合法路径即可。
        return hasPath(root.left, remaining)
                || hasPath(root.right, remaining);
    }
}

class Solution {
    public int sumNumbers(TreeNode root) {
        return dfs(root, 0);
    }

    private int dfs(TreeNode node, int cur) {
        if (node == null) {
            return 0;
        }
        // 路径数字左移一位再拼上当前节点
        cur = cur * 10 + node.val;
        if (node.left == null && node.right == null) {
            return cur;
        }
        return dfs(node.left, cur) + dfs(node.right, cur);
    }
}

import java.util.*; // 用 HashMap 记录根到当前的前缀和出现次数

class Solution {
    private int answer = 0;
    private long target;
    private final Map<Long, Integer> prefixCount = new HashMap<>();

    public int pathSum(TreeNode root, int targetSum) {
        answer = 0;
        prefixCount.clear();
        target = targetSum;
        prefixCount.put(0L, 1); // 空路径前缀和为 0，先记一次才能匹配从根出发的路径。
        dfs(root, 0L);
        return answer;
    }

    private void dfs(TreeNode node, long prefix) {
        if (node == null) return;

        prefix += node.val;

        // prefix 与某个祖先前缀之差为 target，中间这段就是一条合法路径。
        answer += prefixCount.getOrDefault(prefix - target, 0);

        // 先计入再下探，后代才能用到当前前缀。
        prefixCount.put(prefix, prefixCount.getOrDefault(prefix, 0) + 1);

        dfs(node.left, prefix);
        dfs(node.right, prefix);

        // 离开后撤销，避免这条前缀被另一侧兄弟分支误用。
        int remaining = prefixCount.get(prefix) - 1;
        if (remaining == 0) prefixCount.remove(prefix);
        else prefixCount.put(prefix, remaining);
    }
}

import java.util.*; // Java 常用集合、队列、堆与数组工具

class Solution {
    public boolean isValidBST(TreeNode root) {
        // 边界用 long，节点值等于 int 极值时比较仍有效
        return validate(root, Long.MIN_VALUE, Long.MAX_VALUE);
    }

    private boolean validate(TreeNode node, long lower, long upper) {
        if (node == null) return true;

        // 开区间：碰到下界或上界都不是严格 BST
        if (node.val <= lower || node.val >= upper) return false;

        // 左子树不能大于等于当前值，右子树不能小于等于当前值
        return validate(node.left, lower, node.val)
                && validate(node.right, node.val, upper);
    }
}

import java.util.*; // Java 常用集合、队列、堆与数组工具

class Solution {
    public int kthSmallest(TreeNode root, int k) {
        Deque<TreeNode> stack = new ArrayDeque<>();
        TreeNode current = root;

        // 先压完整条左链，弹出顺序就是升序
        while (true) {
            while (current != null) {
                stack.push(current);
                current = current.left;
            }

            current = stack.pop();
            k--;
            // 第 k 次弹出即第 k 小，右侧不必再走
            if (k == 0) return current.val;

            current = current.right;
        }
    }
}

import java.util.*; // 只需按下标切分数组，不必再拷贝区间

class Solution {
    public TreeNode sortedArrayToBST(int[] nums) {
        return build(nums, 0, nums.length - 1);
    }

    private TreeNode build(int[] nums, int left, int right) {
        if (left > right) return null;

        // 中点作根，左右段长度最多差 1，树才能保持高度平衡
        int middle = left + (right - left) / 2;
        TreeNode root = new TreeNode(nums[middle]);

        // 中点已用作根，左右区间都要把它排除
        root.left = build(nums, left, middle - 1);
        root.right = build(nums, middle + 1, right);
        return root;
    }
}

import java.util.*; // Java 常用集合、队列、堆与数组工具

class Solution {
    private int preorderIndex = 0;
    private Map<Integer, Integer> inorderIndex;

    public TreeNode buildTree(int[] preorder, int[] inorder) {
        preorderIndex = 0; // 每次调用从新的前序序列起点开始。
        // 值不重复，用哈希表把根在中序中的位置变成 O(1)
        inorderIndex = new HashMap<>();
        for (int i = 0; i < inorder.length; i++) {
            inorderIndex.put(inorder[i], i);
        }

        return build(preorder, 0, inorder.length - 1);
    }

    private TreeNode build(int[] preorder, int left, int right) {
        if (left > right) return null;

        // 前序里下一个未使用的元素就是当前子树的根
        int rootValue = preorder[preorderIndex++];
        TreeNode root = new TreeNode(rootValue);
        int middle = inorderIndex.get(rootValue);

        // 先左后右，preorderIndex 才按前序往前走
        root.left = build(preorder, left, middle - 1);
        root.right = build(preorder, middle + 1, right);
        return root;
    }
}

import java.util.*;

class Solution {
    private final Map<Integer, Integer> inorderIndex = new HashMap<>();
    private final List<Integer> postorder = new ArrayList<>();

    public int[] getPostorder(int[] preorder, int[] inorder) {
        inorderIndex.clear();
        postorder.clear();
        for (int i = 0; i < inorder.length; i++) {
            inorderIndex.put(inorder[i], i);
        }

        buildPostorder(preorder, 0, preorder.length - 1, 0, inorder.length - 1);

        int[] answer = new int[postorder.size()];
        for (int i = 0; i < answer.length; i++) {
            answer[i] = postorder.get(i);
        }
        return answer;
    }

    private void buildPostorder(int[] preorder, int preLeft, int preRight,
                                int inLeft, int inRight) {
        if (preLeft > preRight) return;

        int rootValue = preorder[preLeft];
        int rootIndex = inorderIndex.get(rootValue);
        int leftSize = rootIndex - inLeft;

        // 后序是左、右、根，所以先递归两侧，最后才加入根。
        buildPostorder(preorder, preLeft + 1, preLeft + leftSize,
                inLeft, rootIndex - 1);
        buildPostorder(preorder, preLeft + leftSize + 1, preRight,
                rootIndex + 1, inRight);
        postorder.add(rootValue);
    }
}

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class PreInToPost {
    public int[] buildPostorder(int[] preorder, int[] inorder) {
        // 值唯一，用中序下标 O(1) 定位根，避免每次线性查找
        Map<Integer, Integer> indexMap = new HashMap<>();
        for (int i = 0; i < inorder.length; i++) {
            indexMap.put(inorder[i], i);
        }
        List<Integer> postorder = new ArrayList<>();
        dfs(preorder, 0, preorder.length - 1, inorder, 0, inorder.length - 1, indexMap, postorder);
        int[] ans = new int[postorder.size()];
        for (int i = 0; i < postorder.size(); i++) {
            ans[i] = postorder.get(i);
        }
        return ans;
    }

    private void dfs(int[] preorder, int preLeft, int preRight,
                     int[] inorder, int inLeft, int inRight,
                     Map<Integer, Integer> indexMap, List<Integer> postorder) {
        if (preLeft > preRight) {
            return;
        }
        // 前序左端是当前子树根
        int rootVal = preorder[preLeft];
        int rootIndex = indexMap.get(rootVal);
        int leftSize = rootIndex - inLeft;
        // 后序：先左、再右，最后才写根
        dfs(preorder, preLeft + 1, preLeft + leftSize,
                inorder, inLeft, rootIndex - 1, indexMap, postorder);
        dfs(preorder, preLeft + leftSize + 1, preRight,
                inorder, rootIndex + 1, inRight, indexMap, postorder);
        postorder.add(rootVal);
    }
}

import java.util.*; // Java 常用集合、队列、堆与数组工具

class Solution {
    public void flatten(TreeNode root) {
        TreeNode current = root;

        while (current != null) {
            if (current.left != null) {
                // 找左子树的右边界接点；它未必是该子树前序遍历的最后节点。
                TreeNode predecessor = current.left;
                while (predecessor.right != null) {
                    predecessor = predecessor.right;
                }

                // 原右子树接到左链末尾，前序顺序才不断
                predecessor.right = current.right;

                // 左子树整段挪到右侧，并清空 left
                current.right = current.left;
                current.left = null;
            }

            // right 已是展开后的下一个节点
            current = current.right;
        }
    }
}

import java.util.*;

class Solution {
    public TreeNode invertTree(TreeNode root) {
        if (root == null) {
            return null;
        }

        // 队列保存还没交换左右孩子的节点，从根开始。
        Queue<TreeNode> queue = new ArrayDeque<>();
        queue.offer(root);

        while (!queue.isEmpty()) {
            TreeNode node = queue.poll();

            // 先交换当前节点，孩子稍后再入队处理。
            TreeNode temp = node.left;
            node.left = node.right;
            node.right = temp;

            // 交换后的非空孩子入队，保证每个节点都会被交换一次。
            if (node.left != null) {
                queue.offer(node.left);
            }
            if (node.right != null) {
                queue.offer(node.right);
            }
        }

        return root;
    }
}

class Solution {
    public TreeNode pruneTree(TreeNode root) {
        if (root == null) return null;

        // 先剪孩子，当前节点才能根据剪完后的左右判断自己是否还含 1。
        root.left = pruneTree(root.left);
        root.right = pruneTree(root.right);

        // 值为 0 且左右都空，整棵当前子树不含 1，应删除。
        if (root.val == 0 && root.left == null && root.right == null) {
            return null;
        }

        return root;
    }
}

import java.util.*; // Java 常用集合、队列、堆与数组工具

class Solution {
    public boolean isSymmetric(TreeNode root) {
        if (root == null) return true;
        return isMirror(root.left, root.right);
    }

    private boolean isMirror(TreeNode left, TreeNode right) {
        // 对应位置都空，这一对已经对称。
        if (left == null && right == null) return true;

        // 结构缺一边，或值不同，都不能成镜像。
        if (left == null || right == null || left.val != right.val) return false;

        // 外侧对外侧、内侧对内侧，两边都成立才对称。
        return isMirror(left.left, right.right)
                && isMirror(left.right, right.left);
    }
}

import java.util.*; // Java 常用集合、队列、堆与数组工具

class Solution {
    public TreeNode lowestCommonAncestor(TreeNode root, TreeNode p, TreeNode q) {
        // 空节点没有目标；碰到 p 或 q 就停，让上层判断另一侧是否也找到。
        if (root == null || root == p || root == q) return root;

        TreeNode left = lowestCommonAncestor(root.left, p, q);
        TreeNode right = lowestCommonAncestor(root.right, p, q);

        // 两侧各带回一个目标，当前 root 是它们最深的公共祖先。
        if (left != null && right != null) return root;

        // 只有一侧非空，原样上传：它可能是一个目标，也可能已是该侧的 LCA。
        return (left != null) ? left : right;
    }
}
